[[File:NP-1.jpg|thumb|{{LangSwitch
  |en={{en|1=To even be able to tie the devil to a pillow — Obstinacy overcomes everything.}}
  |de={{de|1=Den Teufel aufs Kissen binden (überwindet starrköpfig selbst den Teufel)}}
  |fr={{fr|1=On peut attacher le diable à un coussin — L'obstination vainc tout.}}
  |nl={{nl|1=De duivel op het kussen binden — Met elke man raad weten.}}
  |cs={{cs|1=Chcete-li, je dokonce možné uvázat ďábla na polštář - tvrdohlavost překonává všechno}}
  |ro={{ro|1=''A fi capabil chiar și să-l lege pe diavol cu perina.'' — Încăpățânarea învinge totul.}}
  |ru={{ru|1=«Быть способным привязать даже дьявола к подушке» — упрямство, преодолевающее всё}}
}}]]

[[File:NP-9.jpg|thumb|{{LangSwitch
  |en={{en|1=To always gnaw on a single bone — To continually talk about the same subject.}}
  |fr={{fr|1=Toujours mordre le même os — Toujours parler du même sujet/radoter.}}
  |nl={{nl|1=Altijd aan één been knagen — Langdurig vergeefs bezig zijn.}}
  |cs={{cs|1=Pořád okousávat tu stejnou kost - Mluvit stále na stejné téma.}}
  |ro={{ro|1=''A roade întotdeauna un singur os.'' — A vorbi în continuu despre același subiect.}}
  |ru={{ru|1=«Всегда глодать одну и ту же кость» — постоянно говорить на одну и ту же тему}}
}}]]

[[File:NP-30.jpg|thumb|{{LangSwitch
  |en={{en|1=To shave the fool without lather — To trick somebody.}}
  |de={{de|1=Jemanden über den Löffel barbieren (mit jemandem Spott treiben)}}
  |fr={{fr|1=Raser quelqu'un sans savon — jouer un tour à quelqu'un.}}
  |nl={{nl|1=Ergens de gek mee scheren — Iets of iemand bespotten.}}
  |ro={{ro|1=''A bărbieri prostul fără spumă.'' — A înșela pe cineva.}}
  |ru={{ru|1=«Брить дурака без мыла»&nbsp;— Дурить кого-либо.}}
}}]]

[[File:NP-45.jpg|thumb|{{LangSwitch
  |en={{en|1=Anybody can see through an oak plank if there is a hole in it — There is no point in stating the obvious.}}
  |fr={{fr|1=Tout le monde peut voir à travers une planche de chêne si elle a un trou — Rien ne sert d'enfoncer des portes ouvertes.}}
  |nl={{nl|1=Hij kan door een eiken plank zien als er een gat in zit — Hij lijkt alleen maar een wonderdokter / hij is niet zo bijzonder als hij zich voordoet.}}
  |ro={{ro|1=''Oricine poate vedea printr-o scândură de stejar dacă este o gaură în ea.'' — Este inutil să faci afirmații care sunt de la sine înţelese.}}
  |ru={{ru|1=«Каждый может смотреть сквозь дубовую доску, если в ней есть дыра» — Нет смысла констатировать очевидное}}
}}]]

[[File:NP-95.jpg|thumb|{{LangSwitch
  |en={{en|1=The pitcher goes to the water until it finally breaks — 1: Everything has its limitations. 2: Who doesn't take good advice, will suffer the consequences sooner or later.}}
  |de={{de|1=Der Krug geht so lange zum Brunnen, bis er bricht — Alles hat seine Grenzen}}
  |fr={{fr|1=Tant va la cruche à l'eau, qu'à la fin elle se brise — Même sens en français.}}
  |nl={{nl|1=De kruik gaat zolang te water tot zij barst — 1: Alles heeft zijn beperkingen. 2: De onvoorzichtige die niet naar goede raad wil luisteren, ondervindt daarvan vroeg of laat de gevolgen.}}
  |ro={{ro|1=''Ulciorul merge la apă până se sparge în cele din urmă.'' — Ulciorul nu merge de multe ori la apă; totul are limitele sale.}}
  |ru={{ru|1=«Кувшин ходит по воду, пока не разобьётся» — У всего есть предел.}}
}}]]

[[File:Rosen vor die Säue.jpg|thumb|{{LangSwitch
  |en={{en|1=To cast roses before swine — To waste effort on the unworthy.}}
  |de={{de|1=Rosen (Perlen) vor die Säue werfen (Verschwendung an Unwürdige)}}
  |fr={{fr|1=Jeter des roses aux pieds des cochons — Donner de la confiture aux cochons.}}
  |nl={{nl|1=Met moet geen rozen (paarlen) voor de zwijnen werpen — Geld of moeite verspillen aan iets nutteloos.}}
  |ro={{ro|1=''A arunca trandafiri înaintea porcilor.'' — A irosi efortul pe cei nedemni.}}
  |ru={{ru|1=«Бросать розы перед свиньями» — Тратить ценное на недостойных.}}
}}]]
